package com.instaclone.model;
import jakarta.persistence.*;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true,nullable=false) private String username; private String password,fullName,bio,profileImage; public Long getId(){return id;} public String getUsername(){return username;} public void setUsername(String x){username=x;} public String getPassword(){return password;} public void setPassword(String x){password=x;} public String getFullName(){return fullName;} public void setFullName(String x){fullName=x;} public String getBio(){return bio;} public void setBio(String x){bio=x;} public String getProfileImage(){return profileImage;} public void setProfileImage(String x){profileImage=x;} }
